class nglVector {
public:
    float x, y, z, w;

    nglVector() {}
    nglVector(float _x, float _y, float _z, float _w = 1.0f)
        : x(_x), y(_y), z(_z), w(_w) {}

    float &operator[](int i) { return (&x)[i]; }
};

struct vector2d {
    float x, y;
};

struct BeachFrontEnd {
    char pad0[0x9c4];
    bool offset_set;
    char pad1[3];
    vector2d map_points_offset;
    vector2d map_points_multiplier;
    char pad2[0x534];
    bool in_frontend;

    void SetOffset();
    void ReadjustBeachPoints();
    void UpdateBeach(bool reset_challenge);
};

extern void nglProjectPoint(nglVector &, nglVector &)
    __asm__("nglProjectPoint__FR9nglVectorT0");
extern void unadjustCoords(float &, float &)
    __asm__("unadjustCoords__H1Zf_RX01T0_v");

__asm__(".equ nglProjectPoint__FR9nglVectorT0, 0x00399458");
__asm__(".equ unadjustCoords__H1Zf_RX01T0_v, 0x001D6BF0");
__asm__(".equ ReadjustBeachPoints__13BeachFrontEnd, 0x001942A0");
__asm__(".equ UpdateBeach__13BeachFrontEndb, 0x00191508");

void BeachFrontEnd::SetOffset()
{
    if(!in_frontend) return;

    nglVector start_in(-2.079f, 2.080f, -1.676f);
    nglVector end_in(-2.079f, 1.276f, -0.604f);
    nglVector start_out, end_out;

    nglProjectPoint(start_out, start_in);
    nglProjectPoint(end_out, end_in);

    unadjustCoords(start_out[0], start_out[1]);
    unadjustCoords(end_out[0], end_out[1]);

    map_points_offset.x = start_out[0];
    map_points_offset.y = start_out[1];

    map_points_multiplier.x = (end_out[0] - start_out[0])/640.0f;
    map_points_multiplier.y = (end_out[1] - start_out[1])/480.0f;

    offset_set = true;
    ReadjustBeachPoints();
    UpdateBeach(false);
}
